rules:
rules_version = '2';

service firebase.storage {
  match /b/{bucket}/o {
    // Rules for profile pictures directory
    match /users/{userId}/{allPaths=**} {
      // Allow public reads so profile pictures load for other users if needed
      allow read: if true;
      // Allow write actions only if authenticated and requesting for own user directory
      allow write: if request.auth != null && request.auth.uid == userId;
    }
  }
}
